    const t0 = performance.now();
    const items = Array.from({ length: 1000 }, (_, i) => ({
        id: `item-${i + 1}`,
        code: `LOG-${1000 + i}`,
        title: `High-Frequency Telemetry Packet #${i + 1}`,
        category: i % 3 === 0 ? 'Network' : (i % 3 === 1 ? 'Database' : 'Security'),
        latency: `${(Math.random() * 20 + 2).toFixed(1)}ms`,
        status: i % 4 === 0 ? 'Warning' : 'Healthy'
    }));
    $data.virtual_items = items;
    $data.virtual_render_time = (performance.now() - t0).toFixed(2);

